head.script:
scwin.screenId = "jldfil15600";

///////// 1. 변수 및 선언 영역 /////////

scwin.isuSchdlDdStr = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("keyword"))); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil15600.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15600.btn_Search_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15600.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_briefList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_briefList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_briefList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_briefList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.viewBrief === 'function') { await scwin.viewBrief(r["disclsBriefPublIsu"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewBrief (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewBrief'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_briefList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/brief.do",
        ref: "dma_SearchReq",
        target: "dlt_briefList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil15600.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_75").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.briefForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchBriefList');
    frm.action = 'brief.do';
    frm.target = '';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewBrief
 * @author Inswave
 * @date 2026. 09. 29
 * @param _briefNm
 * @returns
 * @hidden N
*/
scwin.viewBrief = async function (_briefNm) {
    /* sdd-asis-lifecycle:begin fn_ViewBrief — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fileUrl = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "briefDir" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("briefDir"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "briefDir" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("briefDir")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "briefDir" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("briefDir"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "briefDir" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("briefDir"))))) + '/${briefPrefix}' + _briefNm + '.html';
    const frm = (document.viewForm || { elements: [] });
    frm.target = '_blank';
    frm.action = fileUrl;
    await moveUrl(fileUrl, {});
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_75_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_75_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_75.page' }); } scwin.tx_fn_Search(); };
